def process_data(records):
    aggregate_value = 0.0
    skipped_items = []
    for item in records:
        try:
            if not isinstance(item['quantity'], int):
                raise TypeError()
            aggregate_value += item['amount'] * item['quantity']
        except (KeyError, TypeError):
            if isinstance(item, dict):
                skipped_items.append(item.get('id'))
            else:
                skipped_items.append(None)
    return aggregate_value, skipped_items
